<template><el-dialog v-model="visible" title="生产与仓储配置" width="min(1050px,95vw)" class="storage-dialog" :before-close="close" :close-on-click-modal="false"><el-alert v-if="error" :title="error" type="error" :closable="false"/><el-button v-if="error" :disabled="busy" @click="load">重新读取并核对</el-button><el-form v-loading="loading" label-position="top" :disabled="busy||unknown"><template v-if="kind==='material'"><el-form-item label="计量方式" required><el-select v-model="form.measurementMode"><el-option label="计重" value="WEIGHT"/><el-option label="计件" value="PIECE"/></el-select></el-form-item><el-form-item label="材料形态" required><el-select v-model="form.form"><el-option v-for="(label,value) in forms" :key="value" :value="value" :label="label"/></el-select></el-form-item></template><el-form-item v-if="kind==='process'" label="工艺类别" required><el-select v-model="form.semanticCode"><el-option label="普通工序" value="NORMAL"/><el-option label="酸洗" value="ACID_WASH"/><el-option label="融定" value="SMELTING"/></el-select></el-form-item><el-table v-if="kind==='product'" :data="form.steps" border><el-table-column prop="processName" label="工序"/><el-table-column label="工艺类别"><template #default="{row}">{{ ({NORMAL:"普通工序",ACID_WASH:"酸洗",SMELTING:"融定"} as Record<string,string>)[row.semanticCode] || "未配置" }}</template></el-table-column><el-table-column label="产出类别"><template #default="{row}"><el-select v-model="row.outputCategory"><el-option label="原材料" value="RAW"/><el-option label="半成品" value="SEMI"/><el-option label="成品" value="PRODUCT"/></el-select></template></el-table-column><el-table-column label="计量方式"><template #default="{row}"><el-select v-model="row.measurementMode"><el-option label="计重" value="WEIGHT"/><el-option label="计件" value="PIECE"/></el-select></template></el-table-column><el-table-column label="原材料产出"><template #default="{row}"><el-select v-if="row.outputCategory==='RAW'" v-model="row.outputMaterialId" filterable><el-option v-for="m in materials" :key="m.id" :value="m.id" :label="m.name||m.code"/></el-select><span v-else>—</span></template></el-table-column><el-table-column label="产出形态"><template #default="{row}"><el-select v-if="row.outputCategory==='RAW'" v-model="row.outputForm"><el-option v-for="(label,value) in forms" :key="value" :value="value" :label="label"/></el-select></template></el-table-column></el-table></el-form><template #footer><el-button :disabled="busy||unknown" @click="close()">取消</el-button><el-button type="primary" :loading="busy" :disabled="loading||!!error||unknown" @click="save">保存</el-button></template></el-dialog></template>
<script setup lang="ts">
import {ref} from 'vue'
import {ElMessage,ElMessageBox} from 'element-plus'
import request from '@/utils/request'
import useUserStore from '@/store/modules/user'
import {message} from './client'
const user=useUserStore(),visible=ref(false),kind=ref(''),form=ref<any>({}),materials=ref<any[]>([]),loading=ref(false),busy=ref(false),unknown=ref(false),error=ref(''),forms={POWDER:'粉状',UNTREATED:'未处理料',METAL:'金属料'}
let id='',factoryId='',epoch=0,initial='',submitted:any=null
const account=()=>JSON.stringify([user.id,user.token,user.sessionEpoch])
async function open(k:string,row:any){kind.value=k;id=String(row.id);factoryId=String(row.factoryId);visible.value=true;unknown.value=false;submitted=null;await load()}
async function load(){const round=++epoch,who=account();loading.value=true;error.value='';try{const r:any=await request({url:`/metal/storage-config/${kind.value}/${id}`,params:{factoryId},quiet:true});if(round!==epoch||who!==account())return;form.value=r.data;if(kind.value==='product')materials.value=r.data.materials||[];if(unknown.value){ElMessage.info('已重新读取服务器配置，请核对后再修改');unknown.value=false;submitted=null}initial=JSON.stringify(form.value)}catch(e){if(round===epoch)error.value=message(e)}finally{if(round===epoch)loading.value=false}}
async function save(){if(busy.value||unknown.value)return;if(kind.value==='material'&&(!form.value.measurementMode||!form.value.form)||kind.value==='process'&&!form.value.semanticCode||kind.value==='product'&&(!form.value.steps?.length||form.value.steps.some((s:any)=>!s.outputCategory||!s.measurementMode||s.outputCategory==='RAW'&&(!s.outputMaterialId||!s.outputForm)))){ElMessage.warning('请补齐必填配置');return}busy.value=true;const who=account();submitted=JSON.parse(JSON.stringify({...form.value,factoryId}));try{await request({url:`/metal/storage-config/${kind.value}/${id}`,method:'put',data:submitted,headers:{repeatSubmit:false},quiet:true});if(who===account()){visible.value=false;ElMessage.success('配置已保存')}}catch(e:any){if(who===account()){unknown.value=!!e?.isAxiosError&&(!e.response||e.response.status>=500);error.value=unknown.value?'保存结果未知，请重新读取服务器配置并核对，不能直接重复提交':message(e)}}finally{busy.value=false}}
async function close(done?:()=>void){if(busy.value||unknown.value)return;if(JSON.stringify(form.value)!==initial)try{await ElMessageBox.confirm('放弃未保存的配置？','确认')}catch{return}++epoch;visible.value=false;done?.()}
defineExpose({open})
</script>
<style scoped>:deep(.el-form-item__label){text-align:left}:deep(.el-input__inner){text-align:left}</style>
